import{_ as r,l as i,o as e,c as l,v as t,p as s,x as o,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"数位 DP","description":"","frontmatter":{"title":"数位 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/digit-dp.md","filePath":"cs/digit-dp.md","lastUpdated":1789023840000}'),h={name:"cs/digit-dp.md"};function _(P,a,m,u,D,E){const d=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="数位-dp" tabindex="-1">数位 DP <a class="header-anchor" href="#数位-dp" aria-label="Permalink to &quot;数位 DP&quot;">​</a></h1><div class="epigraph"><p>把 $[0,n]$ 的计数写成沿十进制位的自动机 DP：是否贴上界、是否前导零、以及题目要的模或数字特征。</p><footer>—— 据数字位 DP 的标准教材技法；自动机计数对照[KMP](/cs/kmp) 整理</footer></div><p>上一课<a href="/cs/tree-dp">树形 DP</a>沿树边。本课对象是整数的十进制（或 \\(b\\) 进制）写法。缺口是数位 DP：<code>dfs(pos, tight, lead, state)</code> 记忆化。不重写树合并。后课单调队列优化换转移形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计 \\([l,r]\\) 中满足性质的个数 \\(=F(r)-F(l-1)\\)。\\(F(n)\\)：从高位填，<code>tight</code> 表示是否等于 \\(n\\) 的前缀；<code>lead</code> 前导零；<code>state</code> 为模、是否出现 49、与模式串匹配等。位数 \\(O(\\log n)\\)，状态乘 tight/lead 仍小。</p><p>缺口是这台自动机，不是 Lucas 模 \\(p\\) 组合数（那是另一计数）。</p><h3 id="前导零不是装饰" tabindex="-1">前导零不是装饰 <a class="header-anchor" href="#前导零不是装饰" aria-label="Permalink to &quot;前导零不是装饰&quot;">​</a></h3><p>「含数字 0 的个数」对前导零敏感。<code>lead</code> 要把未真正开始的位数排除。不要漏。</p><p><span class="marginnote">数位 DP 是竞赛标准。与自动机：KMP 失败函数可做 <code>state</code>。后课单调队列优化数值 DP 转移，不是位数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拆位数组。记忆化。进制 \\(b\\) 同构。区间减。性质用 <code>state</code> 压缩。</p>',11)),(e(),s(p,null,{default:o(()=>[c(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E4%B8%8A%E7%95%8C%20n%20%E7%9A%84%E5%90%84%E4%BD%8D%22%5D%20--%3E%20POS%5B%22%E4%BB%8E%E9%AB%98%E5%88%B0%E4%BD%8E%E5%A1%AB%22%5D%0A%20%20POS%20--%3E%20ST%5B%22tight%20%2F%20lead%20%2F%20state%22%5D%0A%20%20ST%20--%3E%20MEM%5B%22%E8%AE%B0%E5%BF%86%E5%8C%96%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>无上界（无穷）不适合本模板。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>贴界时下一数字上限为 \\(n\\) 的该位，否则 \\(0..b-1\\)。与生成函数：数位 DP 是有限自动机接受的整数计数。与状压：掩码可做 <code>state</code>（出现过的数字集合）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 \\(n\\) 为 \\(10^{10^6}\\) 的大数位（要矩阵或自动机最短路）。后课默认：\\([l,r]\\) 数字性质用数位 DP。下一课单调队列优化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(F(r)-F(l-1)\\)；沿位、贴界、前导零。</li><li><code>state</code> 编码性质或自动机。</li><li>位数对数，状态要小。</li><li>出处：数位 DP 标准技法；自动机见 Knuth–Morris–Pratt 思想。</li></ul>',7))])}const B=r(h,[["render",_]]);export{b as __pageData,B as default};
